#[macro_export]

macro_rules! root_span {
    // Vanilla root span, with no additional fields
    ($request:ident) => {
        $crate::root_span!($request,)
    };
    // Vanilla root span, with a level but no additional fields
    (level = $lvl:expr, $request:ident) => {
        $crate::root_span!(level = $lvl, $request,)
    };
    // One or more additional fields, comma separated, without a level
    ($request:ident, $($field:tt)*) => {
        $crate::root_span!(level = tracing::Level::INFO, $request, $($field)*)
    };
    // One or more additional fields, comma separated
    (level = $lvl:expr, $request:ident, $($field:tt)*) => {
        {
            let user_agent = $request
                .headers()
                .get("User-Agent")
                .map(|h| h.to_str().unwrap_or(""))
                .unwrap_or("");
            let http_route: std::borrow::Cow<'static, str> = $request
                .match_pattern()
                .map(Into::into)
                .unwrap_or_else(|| "default".into());
            let http_method = $crate::middleware::root_span_macro::private::http_method_str($request.method());
            let connection_info = $request.connection_info();
            let request_id = $crate::middleware::root_span_macro::private::get_request_id($request);

            macro_rules! inner_span {
                ($level:expr) => {
                    $crate::middleware::root_span_macro::private::tracing::span!(
                        $level,
                        "HTTP request",
                        kind = "http.request",
                        http.method = %http_method,
                        http.route = %http_route,
                        http.flavor = %$crate::middleware::root_span_macro::private::http_flavor($request.version()),
                        http.scheme = %$crate::middleware::root_span_macro::private::http_scheme(connection_info.scheme()),
                        http.host = %connection_info.host(),
                        http.client_ip = %$crate::middleware::root_span_macro::private::gated_client_ip($request),
                        http.user_agent = %user_agent,
                        http.target = %$request.uri().path_and_query().map(|p| p.as_str()).unwrap_or(""),
                        http.status_code = $crate::middleware::root_span_macro::private::tracing::field::Empty,
                        otel.name = %format!("HTTP {} {}", http_method, http_route),
                        otel.kind = "server",
                        otel.status_code = $crate::middleware::root_span_macro::private::tracing::field::Empty,
                        trace_id = $crate::middleware::root_span_macro::private::tracing::field::Empty,
                        request_id = %request_id,
                        exception.trace_json = $crate::middleware::root_span_macro::private::tracing::field::Empty,
                        client.span_id = $crate::middleware::root_span_macro::private::tracing::field::Empty,
                        tracing_session.id = $crate::middleware::root_span_macro::private::tracing::field::Empty,
                        // Supplied as a creation-time field (like `tracing_session.id`
                        // below) so it lands inline in the span's `open` record rather
                        // than as a detached post-creation `field` op. `None` (an
                        // unstamped one-shot CLI that never called
                        // `set_app_version_stamp`) records nothing, so those processes
                        // don't grow a blank field. Plain `Value` form, not `%`:
                        // `Option<&str>` records through the `Value` trait.
                        app.version = $crate::app_version_stamp().map(|s| s.combined()),
                        $($field)*
                    )
                };
            }
            let span = match $lvl {
                tracing::Level::TRACE => inner_span!(tracing::Level::TRACE),
                tracing::Level::DEBUG => inner_span!(tracing::Level::DEBUG),
                tracing::Level::INFO => inner_span!(tracing::Level::INFO),
                tracing::Level::WARN => inner_span!(tracing::Level::WARN),
                tracing::Level::ERROR => inner_span!(tracing::Level::ERROR),
            };
            std::mem::drop(connection_info);

            span
        }
    };
}

#[doc(hidden)]
pub mod private {
  //! This module exposes and re-exports various functions and traits as public in order to leverage them
  //! in the code generated by the `root_span` macro.
  //! Items in this module are not part of the public interface of `tracing-actix-web` - they are considered
  //! implementation details and will change without notice in patch, minor and major releases.

  use actix_web::dev::ServiceRequest;
  use actix_web::http::{Method, Version};
  use std::borrow::Cow;

  use crate::middleware::request_id::RequestId;
  pub use tracing;

  #[doc(hidden)]
  #[inline]
  pub fn http_method_str(method: &Method) -> Cow<'static, str> {
    match method {
      &Method::OPTIONS => "OPTIONS".into(),
      &Method::GET => "GET".into(),
      &Method::POST => "POST".into(),
      &Method::PUT => "PUT".into(),
      &Method::DELETE => "DELETE".into(),
      &Method::HEAD => "HEAD".into(),
      &Method::TRACE => "TRACE".into(),
      &Method::CONNECT => "CONNECT".into(),
      &Method::PATCH => "PATCH".into(),
      other => other.to_string().into(),
    }
  }

  #[doc(hidden)]
  #[inline]
  pub fn http_flavor(version: Version) -> Cow<'static, str> {
    match version {
      Version::HTTP_09 => "0.9".into(),
      Version::HTTP_10 => "1.0".into(),
      Version::HTTP_11 => "1.1".into(),
      Version::HTTP_2 => "2.0".into(),
      Version::HTTP_3 => "3.0".into(),
      other => format!("{other:?}").into(),
    }
  }

  #[doc(hidden)]
  #[inline]
  pub fn http_scheme(scheme: &str) -> Cow<'static, str> {
    match scheme {
      "http" => "http".into(),
      "https" => "https".into(),
      other => other.to_string().into(),
    }
  }

  #[doc(hidden)]
  pub fn get_request_id(request: &ServiceRequest) -> RequestId {
    use actix_web::HttpMessage;

    request.extensions().get::<RequestId>().cloned().unwrap()
  }

  /// Peer-gated client IP for the `http.client_ip` span field. actix's
  /// `realip_remote_addr()` trusts `Forwarded` / `X-Forwarded-For`, which an
  /// untrusted origin scanner can forge. So: only use `realip_remote_addr()`
  /// when the direct TCP peer is trusted (loopback / private / Cloudflare
  /// egress); otherwise fall back to the raw peer address.
  #[doc(hidden)]
  pub fn gated_client_ip(request: &ServiceRequest) -> String {
    let trusted = request
      .peer_addr()
      .map(|addr| crate::trusted_proxy::is_trusted_proxy(addr.ip()))
      .unwrap_or(false);
    let info = request.connection_info();
    let ip = if trusted {
      info.realip_remote_addr()
    } else {
      info.peer_addr()
    };
    ip.unwrap_or("").to_owned()
  }
}
